"""inventory-api: a small FastAPI service with a Redis cache, used throughout the course."""

import hashlib
import json
import os
import socket
import time

import redis
from fastapi import FastAPI, HTTPException, Response
from redis.backoff import NoBackoff
from redis.retry import Retry

APP_VERSION = os.environ.get("APP_VERSION", "1.0.0")
CACHE_TTL_SECONDS = int(os.environ.get("CACHE_TTL_SECONDS", "30"))
SLOW_LOOKUP_SECONDS = float(os.environ.get("SLOW_LOOKUP_SECONDS", "0.5"))

# Stands in for a database table.
CATALOGUE = {
    "sku-1001": {"name": "Hard hat", "stock": 42},
    "sku-1002": {"name": "Safety boots", "stock": 7},
    "sku-1003": {"name": "Hi-vis vest", "stock": 0},
}

cache = redis.Redis(
    host=os.environ.get("REDIS_HOST", "localhost"),
    port=int(os.environ.get("REDIS_PORT", "6379")),
    password=os.environ.get("REDIS_PASSWORD") or None,
    socket_connect_timeout=1,
    socket_timeout=1,
    retry=Retry(NoBackoff(), 0),  # fail fast: the service still works without its cache
    decode_responses=True,
)

app = FastAPI(title="inventory-api")


@app.get("/")
def index():
    return {"service": "inventory-api", "version": APP_VERSION, "host": socket.gethostname()}


@app.get("/healthz")
def healthz():
    """Liveness: the process is up and answering."""
    return {"status": "ok"}


@app.get("/readyz")
def readyz(response: Response):
    """Readiness: the service can reach its cache, so it can do real work."""
    try:
        cache.ping()
    except redis.RedisError:
        response.status_code = 503
        return {"status": "waiting for redis"}
    return {"status": "ready"}


@app.get("/items/{sku}")
def get_item(sku: str):
    key = f"item:{sku}"
    try:
        cached = cache.get(key)
    except redis.RedisError:
        cached = None  # carry on without the cache
    if cached:
        return {"sku": sku, **json.loads(cached), "cache": "hit"}
    if sku not in CATALOGUE:
        raise HTTPException(status_code=404, detail="unknown sku")
    time.sleep(SLOW_LOOKUP_SECONDS)  # a slow database query
    item = CATALOGUE[sku]
    try:
        cache.setex(key, CACHE_TTL_SECONDS, json.dumps(item))
    except redis.RedisError:
        pass
    return {"sku": sku, **item, "cache": "miss"}


@app.post("/visits")
def add_visit():
    """Count a visit in Redis, so every replica shares one total."""
    return {"visits": cache.incr("visits"), "host": socket.gethostname()}


@app.get("/work")
def work(ms: int = 100):
    """Keep a CPU busy for about `ms` milliseconds, so the autoscaler has something to react to."""
    deadline = time.perf_counter() + min(ms, 2000) / 1000
    rounds = 0
    digest = b"inventory"
    while time.perf_counter() < deadline:
        digest = hashlib.sha256(digest).digest()
        rounds += 1
    return {"rounds": rounds, "host": socket.gethostname()}
